-- ============================================================================
-- 2. RESUMEN DE PROPUESTA
-- ============================================================================

SELECT
    equipo,
    codigo,
    estrategia,
    COUNT(*) AS filas,
    MIN(dia_operacional) AS desde,
    MAX(dia_operacional) AS hasta,
    SUM(old_value) AS suma_actual,
    SUM(new_value) AS suma_propuesta,
    SUM(new_value) - SUM(old_value) AS diferencia
FROM tmp_gnr_correccion
GROUP BY equipo, codigo, estrategia
ORDER BY equipo;

-- ============================================================================
-- 3. VALIDACIONES PREVIAS
--
-- Si algún ID cambió desde que se exportó el CSV, el bloque DO detiene
-- inmediatamente el proceso mediante RAISE EXCEPTION.
-- ============================================================================

DO $$
DECLARE
    v_errores INTEGER;
BEGIN

    SELECT COUNT(*)
    INTO v_errores
    FROM tmp_gnr_correccion t
    LEFT JOIN process."gnrMain" g
        ON g.id = t.id
    WHERE g.id IS NULL;

    IF v_errores > 0 THEN
        RAISE EXCEPTION
            'ABORTADO: existen % IDs que ya no están en gnrMain.',
            v_errores;
    END IF;

    SELECT COUNT(*)
    INTO v_errores
    FROM tmp_gnr_correccion t
    JOIN process."gnrMain" g
        ON g.id = t.id
    WHERE g."nameTag" IS DISTINCT FROM t.codigo
       OR g."dateIn"::date IS DISTINCT FROM t.dia_operacional;

    IF v_errores > 0 THEN
        RAISE EXCEPTION
            'ABORTADO: % filas cambiaron de tag o fecha lógica.',
            v_errores;
    END IF;

    SELECT COUNT(*)
    INTO v_errores
    FROM tmp_gnr_correccion t
    JOIN process."gnrMain" g
        ON g.id = t.id
    WHERE
        (g.value IS NULL) <> (t.old_value IS NULL)
        OR
        (
            g.value IS NOT NULL
            AND t.old_value IS NOT NULL
            AND ABS(g.value - t.old_value)
                > GREATEST(1e-7, ABS(t.old_value) * 1e-9)
        );

    IF v_errores > 0 THEN
        RAISE EXCEPTION
            'ABORTADO: % valores VALUE cambiaron desde la auditoría.',
            v_errores;
    END IF;

    SELECT COUNT(*)
    INTO v_errores
    FROM tmp_gnr_correccion t
    JOIN process."gnrMain" g
        ON g.id = t.id
    WHERE
        (g.accumulated IS NULL) <> (t.old_accumulated IS NULL)
        OR
        (
            g.accumulated IS NOT NULL
            AND t.old_accumulated IS NOT NULL
            AND ABS(g.accumulated - t.old_accumulated)
                > GREATEST(1e-7, ABS(t.old_accumulated) * 1e-9)
        );

    IF v_errores > 0 THEN
        RAISE EXCEPTION
            'ABORTADO: % valores ACCUMULATED cambiaron desde la auditoría.',
            v_errores;
    END IF;

END $$;

-- ============================================================================
-- 4. MUESTREO ANTES DEL UPDATE
-- ============================================================================

SELECT
    t.dia_operacional,
    t.equipo,
    t.codigo,
    t.estrategia,
    t.id,
    g.value AS value_actual,
    t.new_value AS value_propuesto,
    g.accumulated AS accumulated_actual,
    t.new_accumulated AS accumulated_propuesto
FROM tmp_gnr_correccion t
JOIN process."gnrMain" g
    ON g.id = t.id
WHERE
       t.dia_operacional BETWEEN DATE '2026-07-28' AND DATE '2026-08-05'
    OR t.dia_operacional = DATE '2026-01-02'
ORDER BY t.dia_operacional, t.equipo;

-- ============================================================================
-- 5. UPDATE SIMULADO
-- ============================================================================

UPDATE process."gnrMain" AS g
SET
    value       = t.new_value,
    accumulated = t.new_accumulated
FROM tmp_gnr_correccion AS t
WHERE g.id = t.id;

-- ============================================================================
-- 6. VALIDACIÓN POST UPDATE
-- ============================================================================

SELECT
    t.estrategia,
    COUNT(*) AS filas_esperadas,
    COUNT(*) FILTER
    (
        WHERE
            ABS(g.value - t.new_value)
                <= GREATEST(1e-7, ABS(t.new_value) * 1e-9)
            AND
            ABS(g.accumulated - t.new_accumulated)
                <= GREATEST(1e-7, ABS(t.new_accumulated) * 1e-9)
    ) AS filas_correctas
FROM tmp_gnr_correccion t
JOIN process."gnrMain" g
    ON g.id = t.id
GROUP BY t.estrategia
ORDER BY t.estrategia;

SELECT
    t.*,
    g.value AS value_db_despues,
    g.accumulated AS accumulated_db_despues
FROM tmp_gnr_correccion t
JOIN process."gnrMain" g
    ON g.id = t.id
WHERE
       ABS(g.value - t.new_value)
           > GREATEST(1e-7, ABS(t.new_value) * 1e-9)
    OR ABS(g.accumulated - t.new_accumulated)
           > GREATEST(1e-7, ABS(t.new_accumulated) * 1e-9)
ORDER BY t.dia_operacional, t.equipo;

-- ============================================================================
-- 7. VALIDACIÓN VISUAL DE LA TRANSICIÓN HYPET
-- ============================================================================

SELECT
    id,
    "nameMtr",
    "nameTag",
    value,
    accumulated,
    "date",
    "dateIn"
FROM process."gnrMain"
WHERE "nameTag" IN ('hyp400_3', 'hyp500_2')
  AND "dateIn" >= TIMESTAMP '2026-07-29 00:00:00'
  AND "dateIn" <  TIMESTAMP '2026-08-06 00:00:00'
ORDER BY "dateIn", "nameTag", id;

-- ============================================================================
-- 8. PRIMERA EJECUCIÓN = ROLLBACK
-- ============================================================================

ROLLBACK;

